import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Engine and financial core audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/ENGINE-CORE.html"}],["meta",{"property":"og:title","content":"Engine and financial core audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/ENGINE-CORE.html"}],["meta",{"name":"twitter:title","content":"Engine and financial core audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/ENGINE-CORE.md","filePath":"audits/ENGINE-CORE.md","lastUpdated":1794227887000}`),a={name:`audits/ENGINE-CORE.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="engine-and-financial-core-audit" tabindex="-1">Engine and financial core audit <a class="header-anchor" href="#engine-and-financial-core-audit" aria-label="Permalink to “Engine and financial core audit”">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Reviewed the configuration boundary, account/FD models, interest calculation, cash-flow generation, event normalization, outflow handling, provenance, simulation result construction and runtime result assembly.</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to “Findings”">​</a></h2><h3 id="eng-01-—-installment-payout-events-are-bounded-by-the-simulation-period" tabindex="-1">ENG-01 — Installment payout events are bounded by the simulation period <a class="header-anchor" href="#eng-01-—-installment-payout-events-are-bounded-by-the-simulation-period" aria-label="Permalink to “ENG-01 — Installment payout events are bounded by the simulation period”">​</a></h3><p><strong>Current status: IMPLEMENTED ON FOLLOW-UP BRANCH — CI PASSED.</strong> The product&#39;s generated contractual payout sequence is retained, but the authoritative runtime schedules only events within the active simulation window. The product&#39;s maturity must still fit inside the simulation horizon. The run is never extended to accommodate a later installment, and no late installment is clamped to maturity.</p><p><strong>Severity:</strong> P2</p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/models.js" target="_blank" rel="noreferrer">src/core/models.js</a> generates the contractual payout sequence. <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/owner-feedback-followups/src/core/simulation-runtime.js" target="_blank" rel="noreferrer">src/core/simulation-runtime.js</a> filters net payout events against the context start/end before scheduling them. Regression tests cover a five-month tenor / two-month payout interval with five- and six-month simulation windows.</p><p>The complete contractual cash-flow schedule remains on the booking for expected-contract disclosure and total-interest calculations; only the event ledger is bounded. A five-month tenor / two-month interval therefore generates months 2, 4 and 6 contractually, but a five-month simulation schedules only months 2 and 4. With a six-month simulation, all three events are within the requested window. The simulation end date remains exactly the user-selected end date.</p><p><strong>Acceptance:</strong> all scheduled payout events satisfy start-date ≤ event date ≤ end-date; the FD maturity eligibility check remains separate; Greedy/GSS/Absolute R+ replay through the same runtime.</p><h3 id="eng-02-—-leap-year-calculation-is-a-start-year-denominator-not-a-clearly-specified-day-count-convention" tabindex="-1">ENG-02 — Leap-year calculation is a start-year denominator, not a clearly specified day-count convention <a class="header-anchor" href="#eng-02-—-leap-year-calculation-is-a-start-year-denominator-not-a-clearly-specified-day-count-convention" aria-label="Permalink to “ENG-02 — Leap-year calculation is a start-year denominator, not a clearly specified day-count convention”">​</a></h3><p><strong>Current status: FORMULA RETAINED BY OWNER DECISION.</strong> The start-year 365/366 denominator remains unchanged. A concise convention note is available at <a href="./../finance/INTEREST-DAY-COUNT.html">Interest day-count convention</a>. The UI and standalone report now explain that the 365/366 denominator is selected from the accrual start year and applied to the full interval. Reviewed bank product pages publish rates/tenors/payouts but do not establish a universal day-count basis.</p><p><strong>Severity: P2</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/interest.js#L3-L18" target="_blank" rel="noreferrer">src/core/interest.js L3-L18</a>; <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js#L79-L83" target="_blank" rel="noreferrer">src/core/models.js L79-L83</a>.</p><p>When <code>actual_leap_year</code> is enabled, <code>getYearBaseDays</code> selects 365 or 366 from the calendar year of <code>onDate</code>. <code>calcInterest</code> then applies that one denominator to every day in the interval. A cumulative FD spanning multiple calendar years is not split into yearly accrual segments. A tenor starting in a non-leap year and crossing a leap year therefore uses 365 throughout; a tenor starting in a leap year and crossing a non-leap year uses 366 throughout.</p><p><strong>Impact:</strong> results can differ from a bank&#39;s actual/actual, actual/365, actual/366 or other contract-specific basis. The label “Actual leap-year basis” does not make the precise convention clear.</p><p><strong>Recommendation:</strong> define the supported day-count convention explicitly and align the UI/report wording with it. If the intended convention is actual/actual, accrue each calendar-year segment using that year&#39;s denominator. If it is start-year basis, document that and verify it against representative bank terms. Add tests for 1m, 12m and multi-year FDs crossing 29 February in both directions.</p><h3 id="eng-03-—-financial-invariants-are-mostly-distributed-across-constructors-and-runtime-code" tabindex="-1">ENG-03 — Financial invariants are mostly distributed across constructors and runtime code <a class="header-anchor" href="#eng-03-—-financial-invariants-are-mostly-distributed-across-constructors-and-runtime-code" aria-label="Permalink to “ENG-03 — Financial invariants are mostly distributed across constructors and runtime code”">​</a></h3><p><strong>Current status: IMPLEMENTED ON FOLLOW-UP BRANCH — CI PASSED.</strong> FDOption now centrally validates a non-empty label, positive tenor, supported payout type, positive payout interval for non-cumulative products, finite non-negative annual rate and finite non-negative minimum principal. Browser and CLI catalogue loaders isolate invalid rows and log bank file/row diagnostics. Runtime booking continues to enforce maturity within the selected simulation period. Special product caps/tax exemptions remain outside the generic layer until separately modelled.</p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/config-schema.js" target="_blank" rel="noreferrer">config-schema.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/configuration.js" target="_blank" rel="noreferrer">configuration.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js" target="_blank" rel="noreferrer">models.js</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/simulation-runtime.js" target="_blank" rel="noreferrer">simulation-runtime.js</a>.</p><p>The central model boundary now rejects zero-length tenors, invalid payout intervals, negative/non-finite rates and negative/non-finite minimums. A zero minimum remains representable where the source explicitly specifies no minimum. Catalogue loaders reject invalid rows individually with row-level diagnostics, and fail a bank load only when no valid products remain. Age metadata remains validated by the FDOption constructor; special scheme caps and exemptions are deliberately not generic invariants.</p><p><strong>Impact:</strong> a malformed or future catalogue row can reach the calculation model with a structurally valid but financially implausible term.</p><p><strong>Recommendation:</strong> centralize product-term validation in the FDOption construction/load boundary: positive tenor, explicit allowed rate range, positive minimum amount where required, payout interval validity, payout schedule bounds, and consistent age/segment metadata. Keep exceptions for legitimate bank products explicit rather than silently accepting invalid values.</p><h3 id="eng-04-—-ait-is-supplied-as-a-fixed-10-engine-assumption" tabindex="-1">ENG-04 — AIT is supplied as a fixed 10% engine assumption <a class="header-anchor" href="#eng-04-—-ait-is-supplied-as-a-fixed-10-engine-assumption" aria-label="Permalink to “ENG-04 — AIT is supplied as a fixed 10% engine assumption”">​</a></h3><p><strong>Current status: LIGHTWEIGHT ASSUMPTION VERSION ADDED ON FOLLOW-UP BRANCH.</strong> The 10% rate is retained with an assumption ID, effective date and IRD source metadata. UI source disclosure is added. This is not a complete tax-regime model; individual exemptions/relief and non-resident treatment remain outside the calculator&#39;s current input model.</p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/configuration.js#L207-L213" target="_blank" rel="noreferrer">src/core/configuration.js L207-L213</a>.</p><p>The validated configuration returns <code>ait_rate: 0.10</code>; the input schema exposes only an enable/disable switch, not a rate or effective date.</p><p><strong>Impact:</strong> tax rules can change, differ by product or customer, and may include exemptions. A fixed rate can become stale without any obvious indication in a saved scenario or report.</p><p><strong>Recommendation:</strong> make tax assumptions explicit and versioned: rate, effective date, source/reference, applicability and product-level exemptions if supported. At minimum, print the applied AIT rate and an “assumption—verify current tax treatment” note in the report. Do not add tax-exempt catalogue products until the model can enforce their treatment.</p><h3 id="eng-05-—-the-end-value-contract-is-not-explicit-about-outflows" tabindex="-1">ENG-05 — The end-value contract is not explicit about outflows <a class="header-anchor" href="#eng-05-—-the-end-value-contract-is-not-explicit-about-outflows" aria-label="Permalink to “ENG-05 — The end-value contract is not explicit about outflows”">​</a></h3><p><strong>Current status: COMPLETED in PR #75.</strong> <code>SimResult</code> now exposes explicit pre-withdrawal and closing-position getters; see <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/results.js" target="_blank" rel="noreferrer">results.js</a> and the reconciliation tests in <code>tests/js/results.test.js</code>.</p><p>See <a href="./REPORTING-OUTPUTS.html#fin-01-final-value-is-not-the-closing-portfolio-value">Reporting and outputs</a>.</p><p>The engine has both contributed-capital/return arithmetic and ending cash/liability measures. They should have distinct names and contracts. Do not collapse them into one ambiguous “final value” field.</p><h2 id="positive-observations" tabindex="-1">Positive observations <a class="header-anchor" href="#positive-observations" aria-label="Permalink to “Positive observations”">​</a></h2><ul><li>Dates are parsed as strict ISO calendar dates and normalized to UTC-midnight values in <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/dates.js" target="_blank" rel="noreferrer">dates.js</a>.</li><li>The configuration schema rejects unknown top-level, account, schedule and strategy-setting properties.</li><li>Outflow policies are explicit (<code>strict</code>, <code>defer</code>, <code>best_effort</code>) and schedule validation checks account references and date bounds.</li><li>Balance provenance is separated into principal, uncredited interest and counted interest, which supports the goal-credit accounting model.</li><li>The runtime validates account/provenance reconciliation before committing goal-mode state transitions.</li><li>Transfer-fee configuration can use bank-specific same-bank and domestic inter-bank fees plus directed custom overrides.</li></ul><h2 id="tests-to-add" tabindex="-1">Tests to add <a class="header-anchor" href="#tests-to-add" aria-label="Permalink to “Tests to add”">​</a></h2><ul><li>Irregular installment payout periods and the final-payment/maturity invariant.</li><li>Actual/actual versus actual/365 cross-year fixtures with expected bank-contract values.</li><li>Zero/negative tenor, rate, minimum amount and payout interval validation.</li><li>Outflow scenarios proving the distinction between contributed capital, paid withdrawals, outstanding liabilities and closing assets.</li><li>AIT rate/effective-date and tax-exempt product fixtures.</li></ul>`,37)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};